package com.lims.service;

import com.lims.dao.StocktakeDAO;
import com.lims.model.Stocktake;
import com.lims.model.StocktakeDetail;
import com.lims.model.User;
import java.util.*;

public class StocktakeService {
    private final StocktakeDAO dao=new StocktakeDAO();
    private final AuditLogService audit=new AuditLogService();
    public List<User> staff(){return dao.warehouseStaff();}
    public List<Stocktake> managerList(String status){String s=status==null||status.isBlank()?"ALL":status.toUpperCase();if(!Set.of("ALL","ASSIGNED","PENDING_MANAGER","APPROVED","REJECTED","CANCELLED").contains(s))throw new IllegalArgumentException("Trạng thái không hợp lệ.");return dao.managerList(s);}
    public List<Stocktake> assigned(int user){return dao.assignedList(user);}
    public Stocktake find(int id){return dao.find(id);}
    public int create(User manager,String staffValue,String location,String note,String ip,String agent){int staff;try{staff=Integer.parseInt(staffValue);}catch(Exception e){throw new IllegalArgumentException("Hãy chọn nhân viên kho.");}if(dao.warehouseStaff().stream().noneMatch(u->u.getUserId()==staff))throw new IllegalArgumentException("Nhân viên kho không hoạt động hoặc không hợp lệ.");if(location!=null&&location.trim().length()>50)throw new IllegalArgumentException("Vị trí lọc tối đa 50 ký tự.");if(note!=null&&note.trim().length()>255)throw new IllegalArgumentException("Ghi chú tối đa 255 ký tự.");int id=dao.create(manager.getUserId(),staff,location,note);if(id<1)throw new IllegalStateException("Không tạo được đợt kiểm kho.");audit.logAction(manager.getUserId(),manager.getUsername(),"CREATE","INVENTORY_CHECKS",String.valueOf(id),null,Map.of("assignedTo",staff,"locationFilter",location==null?"":location,"note",note==null?"":note),ip,agent);return id;}
    public void submit(User actor,int checkId,String[] ids,String[] products,String[] serials,String[] statuses,String[] locations,String[] reasons,String ip,String agent){int staff=actor.getUserId();Stocktake s=dao.find(checkId);if(s==null||s.getAssignedTo()!=staff||!("ASSIGNED".equals(s.getStatus())||"REJECTED".equals(s.getStatus())))throw new IllegalArgumentException("Đợt kiểm kho không được giao cho bạn hoặc không còn cho phép cập nhật.");int expected=s.getDetails().size();if(ids==null||products==null||serials==null||statuses==null||locations==null||reasons==null||ids.length!=products.length||ids.length!=serials.length||ids.length!=statuses.length||ids.length!=locations.length||ids.length!=reasons.length||ids.length<expected)throw new IllegalArgumentException("Dữ liệu kiểm kho không đầy đủ.");List<StocktakeDetail> rows=new ArrayList<>();Set<Integer> seen=new HashSet<>();Set<String> serialSet=new HashSet<>();
        for(int i=0;i<ids.length;i++){int did;try{did=Integer.parseInt(ids[i]);}catch(Exception e){throw new IllegalArgumentException("Dòng kiểm kho không hợp lệ.");}String serial=serials[i]==null?"":serials[i].trim(),state=statuses[i]==null?"":statuses[i].trim().toUpperCase(),location=locations[i]==null?"":locations[i].trim(),reason=reasons[i]==null?"":reasons[i].trim(),product=products[i]==null?"":products[i].trim();if(did==0&&serial.isEmpty()&&product.isEmpty()&&state.isEmpty()&&location.isEmpty())continue;if(did<0||did>0&&!seen.add(did))throw new IllegalArgumentException("Dòng serial bị lặp.");if(!Set.of("IN_STOCK","DAMAGED","MISSING").contains(state))throw new IllegalArgumentException("Chọn tình trạng thực tế cho mọi máy.");if(serial.isEmpty()||serial.length()>100||!serialSet.add(serial.toUpperCase()))throw new IllegalArgumentException("Serial trống, quá dài hoặc bị lặp trong đợt.");if(did==0){try{int pid=Integer.parseInt(product);if(pid<1)throw new NumberFormatException();StocktakeDetail d=new StocktakeDetail();d.setDetailId(0);d.setProductId(pid);d.setSerialNumber(serial);d.setActualStatus(state);d.setActualLocation(location);d.setDiscrepancyReason(reason);rows.add(d);}catch(Exception e){throw new IllegalArgumentException("Chọn model hợp lệ cho serial ngoài danh sách.");}if(state.equals("MISSING"))throw new IllegalArgumentException("Serial ngoài danh sách phải có trong kho thực tế.");}else{StocktakeDetail original=s.getDetails().stream().filter(d->d.getDetailId()==did).findFirst().orElse(null);if(original==null)throw new IllegalArgumentException("Không được thay đổi các dòng kiểm kho được giao.");if(!original.getSerialNumber().equalsIgnoreCase(serial))throw new IllegalArgumentException("Serial theo hệ thống không thể sửa.");StocktakeDetail d=new StocktakeDetail();d.setDetailId(did);d.setSerialNumber(serial);d.setActualStatus(state);d.setActualLocation(location);d.setDiscrepancyReason(reason);rows.add(d);}
            if(!state.equals("MISSING")&&location.isEmpty())throw new IllegalArgumentException("Vị trí thực tế bắt buộc, trừ trường hợp máy thất lạc.");if(location.length()>50||reason.length()>255)throw new IllegalArgumentException("Vị trí tối đa 50, ghi chú tối đa 255 ký tự.");if((state.equals("MISSING")||did==0||!Objects.equals(location,did>0?s.getDetails().stream().filter(d->d.getDetailId()==did).findFirst().get().getSystemLocation():"" )||did>0&&!Objects.equals(state,s.getDetails().stream().filter(d->d.getDetailId()==did).findFirst().get().getSystemStatus()))&&reason.isEmpty())throw new IllegalArgumentException("Cần ghi lý do cho máy thất lạc hoặc có chênh lệch.");
        }
        if(seen.size()!=expected)throw new IllegalArgumentException("Phải kiểm đếm đủ tất cả serial được giao.");if(!dao.submit(checkId,staff,rows))throw new IllegalStateException("Không gửi được kết quả kiểm kho.");audit.logAction(staff,actor.getUsername(),"SUBMIT","INVENTORY_CHECKS",String.valueOf(checkId),Map.of("status",s.getStatus()),Map.of("status","PENDING_MANAGER","detailCount",rows.size()),ip,agent);
    }
    public void decide(User manager,String checkValue,String action,String reason,String ip,String agent){int id;try{id=Integer.parseInt(checkValue);}catch(Exception e){throw new IllegalArgumentException("Mã đợt kiểm kho không hợp lệ.");}boolean approve="APPROVE".equalsIgnoreCase(action);if(!approve&&!("REJECT".equalsIgnoreCase(action)))throw new IllegalArgumentException("Quyết định không hợp lệ.");String r=reason==null?"":reason.trim();if(!approve&&(r.isEmpty()||r.length()>255))throw new IllegalArgumentException("Nhập lý do từ chối, tối đa 255 ký tự.");if(!dao.decide(id,manager.getUserId(),approve,approve?null:r))throw new IllegalStateException("Không xử lý được đợt kiểm kho; có thể trạng thái đã đổi hoặc tồn kho vừa được cập nhật.");audit.logAction(manager.getUserId(),manager.getUsername(),approve?"APPROVE":"REJECT","INVENTORY_CHECKS",String.valueOf(id),Map.of("status","PENDING_MANAGER"),Map.of("status",approve?"APPROVED":"REJECTED","reason",r),ip,agent);}
}
